func testEventoOperacaoToOneSetOpEventoUsingEvoEveNumeroEvento(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a EventoOperacao
	var b, c Evento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, eventoOperacaoDBTypes, false, strmangle.SetComplement(eventoOperacaoPrimaryKeyColumns, eventoOperacaoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, eventoDBTypes, false, strmangle.SetComplement(eventoPrimaryKeyColumns, eventoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, eventoDBTypes, false, strmangle.SetComplement(eventoPrimaryKeyColumns, eventoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Evento{&b, &c} {
		err = a.SetEvoEveNumeroEvento(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.EvoEveNumeroEvento != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.EvoEveNumeroEventoOperacaos[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.EvoEveNumero != x.EveNumero {
			t.Error("foreign key was wrong value", a.EvoEveNumero)
		}

		zero := reflect.Zero(reflect.TypeOf(a.EvoEveNumero))
		reflect.Indirect(reflect.ValueOf(&a.EvoEveNumero)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.EvoEveNumero != x.EveNumero {
			t.Error("foreign key was wrong value", a.EvoEveNumero, x.EveNumero)
		}
	}
}
